import{_ as l,a0 as i,w as p,s as g,I as s,x as n,a1 as r,A as e,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"全能冠軍：Linux系統性能和使用活動監控工具 sysstat | LCTT x X-CMD","titleTemplate":false,"description":"全能冠軍：Linux系統性能和使用活動監控工具 sysstat | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"全能冠軍：Linux系統性能和使用活動監控工具 sysstat | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"全能冠軍：Linux系統性能和使用活動監控工具 sysstat | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/Sysstat – All-in-One System Performance and Usage Activity Monitoring Tool For Linux","title":"全能冠軍：Linux系統性能和使用活動監控工具 sysstat","tag":"201410","desc":""},"relativePath":"201410/Sysstat – All-in-One System Performance and Usage Activity Monitoring Tool For Linux.md","filePath":"[post].md"}'),u={name:"201410/Sysstat – All-in-One System Performance and Usage Activity Monitoring Tool For Linux.md"};function d(m,t,y,f,S,T){const o=i("Link");return p(),g("div",null,[t[21]||(t[21]=s("h1",{id:"全能冠軍-linux系統性能和使用活動監控工具-sysstat",tabindex:"-1"},[n("全能冠軍：Linux系統性能和使用活動監控工具 sysstat "),s("a",{class:"header-anchor",href:"#全能冠軍-linux系統性能和使用活動監控工具-sysstat","aria-label":"Permalink to “全能冠軍：Linux系統性能和使用活動監控工具 sysstat”"},"​")],-1)),t[22]||(t[22]=s("p",null,[s("strong",null,"Sysstat"),n("是一個非常方便的工具，它帶有眾多的系統資源監控工具，用於監控系統的性能和使用情況。我們在日常使用的工具中有相當一部分是來自sysstat工具包的。同時，它還提供了一種使用cron表達式來制定性能和活動數據的收集計劃。")],-1)),t[23]||(t[23]=s("p",null,[s("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/08/sysstat.png",alt:"Install Sysstat in Linux"})],-1)),t[24]||(t[24]=s("p",null,"下表是包含在sysstat包中的工具",-1)),s("ul",null,[s("li",null,[r(o,{href:"http://linux.cn/article-4024-1.html"},{default:e(()=>[...t[0]||(t[0]=[s("strong",null,"iostat",-1)])]),_:1}),t[1]||(t[1]=n(": 輸出CPU的統計信息和所有I/O設備的輸入輸出（I/O）統計信息。",-1))]),t[2]||(t[2]=a("<li><strong>mpstat</strong>: 關於CPU的詳細信息（單獨輸出或者分組輸出）。</li><li><strong>pidstat</strong>: 關於運行中的進程/任務、CPU、內存等的統計信息。</li><li><strong>sar</strong>: 保存並輸出不同系統資源（CPU、內存、IO、網絡、內核等。。。）的詳細信息。</li><li><strong>sadc</strong>: 系統活動數據收集器，用於收集sar工具的後端數據。</li><li><strong>sa1</strong>: 系統收集並存儲sadc數據文件的二進制數據，與sadc工具配合使用</li><li><strong>sa2</strong>: 配合sar工具使用，產生每日的摘要報告。</li><li><strong>sadf</strong>: 用於以不同的數據格式（CVS或者XML）來格式化sar工具的輸出。</li><li><strong>Sysstat</strong>: sysstat工具的man幫助頁面。</li><li><strong>nfsiostat</strong>: NFS（Network File System）的I/O統計信息。</li><li><strong>cifsiostat</strong>: CIFS(Common Internet File System)的統計信息。</li>",10))]),t[25]||(t[25]=a("<p>最近(在2014年6月17日)，<strong>sysstat 11.0.0</strong>（穩定版）已經發布了，同時還新增了一些有趣的特性，如下：</p><p>pidstat命令新增了一些新的選項：首先是“-R”選項，該選項將會輸出有關策略和任務調度的優先級信息。然後是“<strong>-G</strong>”選項，通過這個選項我們可以使用名稱搜索進程，然後列出所有匹配的線程。</p><p>sar、sadc和sadf命令在數據文件方面同樣帶來了一些功能上的增強。與以往只能使用“<strong>saDD</strong>”來命名數據文件。現在使用<strong>-D</strong>選項可以用“<strong>saYYYYMMDD</strong>”來重命名數據文件，同樣的，現在的數據文件不必放在“<strong>var/log/sa</strong>”目錄中，我們可以使用“SA_DIR”變量來定義新的目錄，該變量將應用與sa1和sa2命令。</p><p>###在Linux系統中安裝sysstat####</p><p>在主要的linux發行版中，‘<strong>sysstat</strong>’工具包可以在默認的程序庫中安裝。然而，在默認程序庫中的版本通常有點舊，因此，我們將會下載源代碼包，編譯安裝最新版本（<strong>11.0.0</strong>版本）。</p><p>首先，使用下面的連接下載最新版本的sysstat包，或者你可以使用<strong>wget</strong>命令直接在終端中下載。</p>",6)),s("ul",null,[s("li",null,[s("p",null,[r(o,{href:"http://sebastien.godard.pagesperso-orange.fr/download.html"},{default:e(()=>[...t[3]||(t[3]=[n("http://sebastien.godard.pagesperso-orange.fr/download.html",-1)])]),_:1})]),t[4]||(t[4]=s("pre",null,[s("code",null,`  # wget http://pagesperso-orange.fr/sebastien.godard/sysstat-11.0.0.tar.gz
`)],-1))])]),t[26]||(t[26]=a(`<p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Download-Sysstat.png" alt="Download Sysstat Package"></p><p><em>下載sysstat包</em></p><p>然後解壓縮下載下來的包，進去該目錄，開始編譯安裝</p><pre><code># tar -xvf sysstat-11.0.0.tar.gz 
# cd sysstat-11.0.0/
</code></pre><p>這裏，你有兩種編譯安裝的方法：</p><p>####a)####</p><p>第一，你可以使用<strong>iconfig</strong>(這將會給予你很大的靈活性，你可以選擇/輸入每個參數的自定義值)</p><pre><code># ./iconfig
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Sysstat-iconfig-Command.png" alt="Sysstat iconfig Command"></p><p><em>sysstat的iconfig命令</em></p><p>####b)####</p><p>第二，你可以使用標準的<strong>configure</strong>，在命令列中定義所有選項。你可以運行 <strong>./configure –help 命令</strong>來列出該命令所支持的所有限選項。</p><pre><code># ./configure --help
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Configure-Help.png" alt="Sysstat Configure Help"></p><p><em>stsstat的cofigure -help</em></p><p>在這裏，我們使用標準的<strong>./configure</strong>命令來編譯安裝sysstat工具包。</p><pre><code># ./configure
# make
# make install	
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Configure-Sysstat.png" alt="Configure Sysstat in Linux"></p><p><em>在Linux系統中配置sysstat</em></p><p>在編譯完成後，我們將會看到一些類似於上圖的輸出。現在運行如下命令來查看sysstat的版本。</p><pre><code># mpstat -V

sysstat version 11.0.0
(C) Sebastien Godard (sysstat &lt;at&gt; orange.fr)
</code></pre><p>###更新Linux 系統中的sysstat###</p><p>默認的，sysstat使用“<strong>/usr/local</strong>”作為其目錄前綴。因此，所有的二進制數據/工具都會安裝在“<strong>/usr/local/bin</strong>”目錄中。如果你的系統已經安裝了sysstat 工具包，則上面提到的二進制數據/工具有可能在“<strong>/usr/bin</strong>”目錄中。</p><p>因為“<strong>$PATH</strong>”變量不包含“<strong>/usr/local/bin</strong>”路徑，你在更新時可能會失敗。因此，確保“<strong>/usr/local/bin</strong>”路徑包含在“$PATH”環境變量中，或者在更新前，在編譯和卸載舊版本時將<strong>-prefix</strong>選項指定值為“<strong>/usr</strong>”。</p><pre><code># yum remove sysstat            [On RedHat based System]
# apt-get remove sysstat        [On Debian based System]
</code></pre><hr><pre><code># ./configure --prefix=/usr
# make
# make install
</code></pre><p>現在，使用‘mpstat’命令的‘<strong>-V</strong>’選項查看更新後的版本。</p><pre><code># mpstat -V

sysstat version 11.0.0
(C) Sebastien Godard (sysstat &lt;at&gt; orange.fr)
</code></pre>`,29)),s("p",null,[t[6]||(t[6]=s("strong",null,"參考",-1)),t[7]||(t[7]=n(": 更多詳細的信息請到 ",-1)),r(o,{href:"http://sebastien.godard.pagesperso-orange.fr/documentation.html"},{default:e(()=>[...t[5]||(t[5]=[n("Sysstat Documentation",-1)])]),_:1})]),t[27]||(t[27]=s("p",null,"在我的下一篇文章中，我將會展示一些sysstat命令使用的實際例子，敬請關注更新。別忘了在下面評論框中留下您寶貴的意見。",-1)),t[28]||(t[28]=s("hr",null,null,-1)),s("p",null,[t[9]||(t[9]=n("via: ",-1)),r(o,{href:"http://www.tecmint.com/install-sysstat-in-linux/"},{default:e(()=>[...t[8]||(t[8]=[n("http://www.tecmint.com/install-sysstat-in-linux/",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=n("作者：",-1)),r(o,{href:"http://www.tecmint.com/author/kuldeepsharma47/"},{default:e(()=>[...t[10]||(t[10]=[n("Kuldeep Sharma",-1)])]),_:1}),t[14]||(t[14]=n(" 譯者：",-1)),r(o,{href:"https://github.com/cvsher"},{default:e(()=>[...t[11]||(t[11]=[n("cvsher",-1)])]),_:1}),t[15]||(t[15]=n(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[12]||(t[12]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=n("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[16]||(t[16]=[n("LCTT",-1)])]),_:1}),t[19]||(t[19]=n(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:e(()=>[...t[17]||(t[17]=[n("Linux中國",-1)])]),_:1}),t[20]||(t[20]=n(" 榮譽推出",-1))])])}const L=l(u,[["render",d]]);export{C as __pageData,L as default};
